public int centeredAverage(int[] nums)
{
    int length = nums.length;
    int smallest = nums[0];
    int largest = nums[0];
    int sPlace = 0;
    int lPlace = 0;
    for (int x = 0; x < nums.length; x++)
    {
        if (smallest > nums[x])
        {
            smallest = nums[x];
            sPlace = x;
            
        }
        if (largest < nums[x])
        {
            largest = nums[x];
            lPlace = x;
        }
    }
    int sum = 0;
    for (int i = 0; i < nums.length; i++)
    {
        sum = sum + nums[i];
    }
    sum = sum - nums[lPlace] - nums[sPlace];
    return sum/(nums.length - 2);
    
}

