public int[] seriesUp(int n)
{
    int[] hi = new int[n * (n + 1) / 2];
    for(int x = hi.length - 1; x >= 0; x--)
    {
        for (int i = 0; i < n; i++)
        {
        	hi[x] = n - i;
            x--;
        }
        x++;
        n = n - 1;
    }
    return hi;
}

